from typing import FrozenSet, Iterable, List

def construct_tower(height: int, base: Iterable[str]) -> List[FrozenSet[str]]:
    if height < 0: raise ValueError("height must be nonnegative")
    current, stages = frozenset(base), []
    for n in range(height + 1):
        stages.append(current)
        current = current | {f"Con(S_{n})"}
    return stages

from typing import List

def simulation_matrix(height: int) -> List[List[int]]:
    if height < 0: raise ValueError("height must be nonnegative")
    return [[int(n >= m) for m in range(height + 1)] for n in range(height + 1)]

from typing import Dict, Iterable, List, Tuple

def forbidden_cycle(vertices: int, edges: Iterable[Tuple[int,int]], strict: Iterable[Tuple[int,int]]) -> bool:
    graph: Dict[int,List[int]] = {v: [] for v in range(vertices)}
    for a,b in edges: graph[a].append(b)
    def reaches(a: int, b: int) -> bool:
        todo, seen = [a], set()
        while todo:
            v=todo.pop()
            if v==b: return True
            if v not in seen: seen.add(v); todo.extend(graph[v])
        return False
    return any(reaches(lower,upper) for upper,lower in strict)

